CustomField.formula:
IF(ISBLANK(Total_Paid_Amount_Archived__c),
	IF(Total_Paid_Amount__c = 0 || ISBLANK(Total_Paid_Amount__c), 
		Amount - IF(ISBLANK(Early_Payout_Adjustment__c), 0, Early_Payout_Adjustment__c),
		IF(Is_Credit_Contract__c, 
			IF(Account.State_Master_State__c = 'NZ', 
				Amount + Total_Additional_Fees__c - Total_Paid_Amount__c - IF(ISBLANK(Early_Payout_Adjustment__c), 0, Early_Payout_Adjustment__c), 
				CC_Remaining_Amount__c - IF(ISBLANK(Early_Payout_Adjustment__c), 0, Early_Payout_Adjustment__c)
			), 
			Total_Scheduled_Amount__c - Total_Paid_Amount__c
		)
	), 
	Amount - Total_Paid_Amount_Archived__c
)
